{"plan_json": "{
  "objectives": [
    {
      "id": 1,
      "objective": "Find experimental studies on effects of fines (<15-20 μm) in Al alloy LPBF powders on flowability, spreadability, packing, porosity, properties",
      "rationale": "Core question 1 - need measured data on how fine particles affect LPBF outcomes for aluminum alloys",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 2,
      "objective": "Find studies on ultrasonically atomized powders (AMAZEMET rePOWDER, ATO Lab, etc.) for LPBF - what PSD cuts they used",
      "rationale": "Core question 2 - need to know what other UA powder users did regarding lower size cuts",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 3,
      "objective": "Find commercial LPBF Al powder specifications (EOS, SLM Solutions, Renishaw, Aconity, etc.) - size ranges and fines limits",
      "rationale": "Core question 3 - need industry standard specs for comparison",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 4,
      "objective": "Research granular Bond number and cohesion physics for Al powders at 10, 20, 45 μm",
      "rationale": "Part of question 1 - the cohesion/van der Waals argument specific to low-density Al",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 5,
      "objective": "Find data on Al dust explosibility vs particle size (MIE, Kst, MEC) between 10-60 μm and NFPA 484 implications",
      "rationale": "Core question 5 - safety considerations for handling fine Al powder",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 6,
      "objective": "Research what reviewers expect for powder characterization in LPBF research papers",
      "rationale": "Core question 4 - defensibility of no lower cut for research builds",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 7,
      "objective": "Create summary artifacts and submit final answer with recommendation",
      "rationale": "Synthesize all findings into a comprehensive answer",
      "status": "pending",
      "result": null,
      "evaluation": null
    }
  ]
}"}

